// Preset profile pictures (CR-006): 12 illustrated characters, no photo upload (nothing to moderate, safe for minors).
// The pictures are static files in public/avatars (generated by tools/avatars/make-avatars.ts with Multiavatar,
// multiavatar.com, credited in the README and under the picker), so no outside service is called.
import { AVATARS, type Avatar } from '../shared/account.ts';

export const AVATAR_CODES = AVATARS;
const isAvatar = (a: string | null | undefined): a is Avatar => !!a && (AVATARS as readonly string[]).includes(a);
const initials = (s: string) => s.replace(/^Sample( senior)? · /, '').split(/[\s·,._]+/).filter(w => /^\p{L}/u.test(w)).slice(0, 2).map(w => w[0]!.toUpperCase()).join('');   // letters only: nimal_123 -> N
const toneOf = (s: string) => ['#1F8A70', '#3461C9', '#B4458C', '#C26B00', '#6A4FC9', '#0E7C9A', '#A33A3A', '#4E7A1E'][[...s].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7) % 8];

/** A person's picture: their chosen character, or their initials on a steady colour. Decorative (the name is shown next to it). */
export function PersonAvatar({ avatar, name, size = 40 }: { avatar: string | null | undefined; name: string; size?: number }) {
  if (isAvatar(avatar)) return <img className="person-avatar" src={`/avatars/${avatar}.svg`} width={size} height={size} alt="" aria-hidden="true" loading="lazy" />;
  return <span className="person-avatar" aria-hidden="true" style={{ width: size, height: size, background: toneOf(name), fontSize: size * 0.38 }}>{initials(name) || '?'}</span>;
}
